-- CIE-MTB-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('CIE-MTB-01-CTX', NULL, 'Las levaduras pueden obtener energía, a partir de los azúcares, por dos vías diferentes. Durante la fermentación una pequeña parte de la energía química contenida en los azúcares (C6H12O6) es convertida a ATP usado por la célula. Durante la respiración celular una mayor cantidad de energía química pasa a ATP disponible para las células, como se muestra en las siguientes ecuaciones:
FERMENTACIÓN: C6H12O6 → 2CO2 + 2C2H5OH + 2 ATP
RESPIRACIÓN CELULAR: C6H12O6 + O2 → 6CO2 + 6H2O + 38 ATP', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
