VALUES ('CIE-MTB-01', (SELECT id FROM subtemas WHERE slug = 'metabolismo-celular'), (SELECT id FROM contextos WHERE codigo = 'CIE-MTB-01-CTX'), 'De acuerdo con estas ecuaciones, es posible afirmar que la', NULL,
