-- CIE-TRT-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('CIE-TRT-01-CTX', NULL, 'Los aminoácidos, transportados por el ARN de transferencia (ARNt), inician el proceso de traducción cuando la información contenida en el ARN mensajero (ARNm) pasa por el ribosoma. Las bases nitrogenadas (anticodón del ARNt y codón del ARNm) se aparean y van uniendo los aminoácidos en el orden necesario para formar una proteína específica.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
INSERT INTO preguntas (codigo, subtema_id, contexto_id, enunciado, imagen_url, imagen_alt, dificultad, competencia,
  explicacion, tiempo_estimado_seg, etiquetas, origen)
VALUES ('CIE-TRT-01', (SELECT id FROM subtemas WHERE slug = 'transcripcion-y-traduccion'), (SELECT id FROM contextos WHERE codigo = 'CIE-TRT-01-CTX'), 'Teniendo en cuenta esta información, ¿qué pasaría ante la ausencia del ARNt en la síntesis de proteínas?', NULL,
  NULL, 2, NULL, '', 120,
  '{}'::text[], 'banco')
ON CONFLICT (codigo) DO UPDATE SET subtema_id = EXCLUDED.subtema_id, contexto_id = EXCLUDED.contexto_id,
  enunciado = EXCLUDED.enunciado, imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt,
  dificultad = EXCLUDED.dificultad, competencia = EXCLUDED.competencia, explicacion = EXCLUDED.explicacion,
  tiempo_estimado_seg = EXCLUDED.tiempo_estimado_seg, etiquetas = EXCLUDED.etiquetas, activa = TRUE;
UPDATE opciones SET es_correcta = FALSE WHERE pregunta_id = (SELECT id FROM preguntas WHERE codigo = 'CIE-TRT-01');
INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-TRT-01'), 'A', 'Se detendría la producción de proteínas, puesto que el ARNt es el encargado de transportar aminoácidos específicos y aparearlos con el fin de iniciar el proceso de elongación.', true, NULL),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-TRT-01'), 'B', 'No se vería afectada la producción de proteínas, ya que depende únicamente del ARNm.', false, NULL),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-TRT-01'), 'C', 'Se aumentaría la producción de proteínas, puesto que el ARNt controla el número de aminoácidos que son transportados al unir al codón y al anticodón en el citoplasma del ribosoma.', false, NULL),
  ((SELECT id FROM preguntas WHERE codigo = 'CIE-TRT-01'), 'D', 'No se vería afectada la producción de proteínas, ya que el ARNt es reemplazado por el ARNm.', false, NULL)
ON CONFLICT (pregunta_id, letra) DO UPDATE SET texto = EXCLUDED.texto, es_correcta = EXCLUDED.es_correcta,
  retroalimentacion = EXCLUDED.retroalimentacion;
-- CIE-TRT-02
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('CIE-TRT-02-CTX', NULL, 'Las proteínas, el ADN y el ARN están formados por unidades más pequeñas. El ADN y el ARN se encuentran formados por bases nitrogenadas y las proteínas por aminoácidos. La producción de estas tres sustancias se encuentra relacionada entre sí, de tal forma que para la producción de proteínas es necesaria la presencia previa de ADN y/o ARN. El siguiente cuadro indica con signo (−) las sustancias que se les suprimen a cuatro cultivos de células:
Sustancia — Cultivo 1 / 2 / 3 / 4
Aminoácidos: − / − / + / +
Bases nitrogenadas: − / + / − / +', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
