-- CIE-RPH-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('CIE-RPH-01-CTX', NULL, 'Un estudiante afirma que el pH no afecta la solubilidad de una sustancia. Con el fin de comprobar su afirmación, el estudiante adiciona la misma cantidad de hidróxido de aluminio a tres recipientes que contienen la misma cantidad de agua con diferente pH. Después de agitar durante 10 minutos, observa lo siguiente: a pH ácido se disuelve totalmente; a pH neutro se disuelve parcialmente; a pH básico no se disuelve.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
