-- MAT-GE2-01
INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('MAT-GE2-01-CTX', NULL, 'La figura muestra las baldosas triangulares equiláteras W y X, cuyos perímetros son 9 cm y 27 cm, respectivamente. Vanesa necesita saber la razón de semejanza que existe entre las baldosas y, para ello, realiza el siguiente procedimiento:
Paso 1. Dividir el perímetro de la baldosa W entre 3.
Paso 2. Dividir el perímetro de la baldosa X entre 3.
Paso 3. Dividir el resultado del paso 2 entre el resultado del paso 1.', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
