INSERT INTO opciones (pregunta_id, letra, texto, es_correcta, retroalimentacion) VALUES
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-GE2-01'), 'A', 'Sí, porque entre los dos triángulos hay 6 lados, y, por lo tanto, se debe determinar la razón entre cada par de lados correspondientes.', false, NULL),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-GE2-01'), 'B', 'No, porque se debe dividir el perímetro entre 3 para obtener la longitud de los lados de cada baldosa.', true, NULL),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-GE2-01'), 'C', 'Sí, porque se debe calcular la razón entre los lados de una baldosa y cada lado de la otra, y, por lo tanto, se deben calcular 6 razones.', false, NULL),
  ((SELECT id FROM preguntas WHERE codigo = 'MAT-GE2-01'), 'D', 'No, porque se debe dividir la longitud de un lado de cada baldosa entre su respectivo perímetro.', false, NULL)
