INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('SOC-DDH-01-CTX', NULL, 'Un grupo de mineros artesanales ha aumentado sus ingresos al encontrar un punto del río en el cual se puede extraer oro con la ayuda de mercurio. La comunidad del municipio aledaño se ha visto afectada, porque el río se ha contaminado con los desechos tóxicos que genera la actividad minera y es la única fuente de agua que tienen los habitantes para el consumo e irrigación de cultivos. Ante esto, la alcaldesa del municipio considera necesario establecer una normatividad que regule este tipo de actividades.', NULL, NULL, NULL)
