INSERT INTO contextos (codigo, titulo, contenido, imagen_url, imagen_alt, fuente)
VALUES ('SOC-HXX-01-CTX', NULL, 'Lea atentamente el siguiente fragmento, tomado de una intervención pública de un famoso líder político del siglo XX: “La libertad se enfrenta a muchas dificultades y la democracia no es perfecta, pero nunca hemos tenido que levantar un muro para encerrar a nuestro pueblo, para prevenir que la gente se vaya. [...] Pese a que el muro es la más obvia y viva demostración del fracaso del sistema comunista a ojos del mundo entero [...] es una ofensa contra la humanidad, que separa familias, divide maridos y esposas, hermanos y hermanas [...]”', NULL, NULL, NULL)
ON CONFLICT (codigo) DO UPDATE SET titulo = EXCLUDED.titulo, contenido = EXCLUDED.contenido,
  imagen_url = EXCLUDED.imagen_url, imagen_alt = EXCLUDED.imagen_alt, fuente = EXCLUDED.fuente;
