  contenido = EXCLUDED.contenido, duracion_min = EXCLUDED.duracion_min, activa = TRUE;
INSERT INTO lecciones (subtema_id, codigo, titulo, resumen, contenido, duracion_min, xp_recompensa, monedas_recompensa, orden)
VALUES ((SELECT id FROM subtemas WHERE slug = 'eventos-canonicos'), 'SOC-EVC-L1', 'Eventos canónicos', '', '[{"tipo":"subtitulo","nivel":2,"texto":"Historia del mundo"},{"tipo":"tabla","encabezado":["Fecha","Hecho"],"filas":[["476","Caída del Imperio romano de Occidente; inicio de la Edad Media"],["800","Carlomagno es coronado emperador"],["Siglos XI a XIII","Cruzadas"],["Siglo XIV","Peste Negra; inicio del Renacimiento"],["1453","Caída de Constantinopla"],["1492","Llegada de Colón a América"],["Siglo XVIII","Ilustración; Revolución Industrial (desde cerca de 1750)"],["1776","Declaración de independencia de Estados Unidos"],["1789","Revolución Francesa"],["1799 a 1815","Napoleón"],["Siglo XIX","Imperialismo"],["1910","Inicio de la Revolución Mexicana"],["1914 a 1918","Primera Guerra Mundial"],["1917","Revolución Rusa"],["1922","Fundación de la URSS"],["1929","Crack de la bolsa y Gran Depresión"],["1939 a 1945","Segunda Guerra Mundial"],["1947 a 1991","Guerra Fría"],["1959","Revolución Cubana"],["1961 a 1989","Muro de Berlín"],["1962","Crisis de los misiles"],["1991","Caída de la Unión Soviética"]]},{"tipo":"subtitulo","nivel":2,"texto":"Historia de Colombia"},{"tipo":"tabla","encabezado":["Fecha","Hecho"],"filas":[["1499","Alonso de Ojeda llega a las costas colombianas"],["1781","Revolución de los Comuneros"],["Hacia 1793","Nariño traduce los Derechos del Hombre"],["1810","Florero de Llorente; inicio de la independencia y de la Patria Boba"],["1815","Reconquista española"],["1819","Batalla de Boyacá"],["Años posteriores a 1830","Disolución de la Gran Colombia; Nueva Granada"],["1886 a 1930","Hegemonía Conservadora"],["1899 a 1902","Guerra de los Mil Días"],["1903","Separación de Panamá"],["1928","Masacre de las bananeras"],["1948","Bogotazo"],["1946 a 1958","La Violencia"],["1953 a 1957","Dictadura de Rojas Pinilla"],["1958 a 1974","Frente Nacional"],["1982","Pablo Escobar, representante a la Cámara suplente"],["1984","Asesinato de Rodrigo Lara Bonilla"],["1985","Toma del Palacio de Justicia"],["1989","Asesinato de Luis Carlos Galán"],["1991","Constitución Política"]]},{"tipo":"subtitulo","nivel":2,"texto":"Apuntes base (carpeta HISTORIA)"},{"tipo":"lista","items":["Historia - Conceptos clave","Historia del mundo I a IV","Historia del siglo XX","Guerra fría","Historia de Latinoamérica","Historia de Colombia I, II y III"],"ordenada":false},{"tipo":"subtitulo","nivel":2,"texto":"Fuentes oficiales del ICFES consultadas"},{"tipo":"lista","items":["ICFES, infografía de la prueba de Sociales y Ciudadanas Saber 11: https://www.icfes.gov.co/wp-content/uploads/2025/09/17-septiembre-infografia-prueba-sociales-y-ciudadanas-saber-11.pdf","ICFES, Marco de referencia de la prueba de Sociales y Ciudadanas Saber 11: https://www.icfes.gov.co/wp-content/uploads/2024/11/Marco-de-referencia-Prueba-de-sociales-y-ciudadanas-saber-11.pdf","ICFES, Guía de orientación Saber 11 (2025): https://www.icfes.gov.co/wp-content/uploads/2025/04/30-abril-guia-orientacion-saber-11o-2025-2.pdf","ICFES, Guía de orientación Saber 11 (2021): https://www.icfes.gov.co/wp-content/uploads/2024/11/Guia-de-orientacion-Saber-11.°-2021-1-Pdf-accesible.pdf"],"ordenada":false}]'::jsonb,
  5, 30, 5, 1)
